begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local timezone='UTC';
select no_plan();

select ok((select bool_and(relrowsecurity) from pg_class where oid in('private.board_operations'::regclass,'private.board_uploads'::regclass)),'board receipts and staged uploads enable RLS');
select ok((select bool_and(not has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) from unnest(array['anon','authenticated','service_role'])r
 cross join unnest(array['private.board_operations','private.board_uploads'])t),'API roles cannot forge or read private board state');
select ok((select count(*)=10 and bool_and(prosecdef and 'search_path=""'=any(proconfig)) from pg_proc where pronamespace='public'::regnamespace and proname like 'board_%'),'ten board RPCs pin security-definer paths');
select ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE') and not has_function_privilege('anon',oid,'EXECUTE') and not has_function_privilege('service_role',oid,'EXECUTE'))
 from pg_proc where pronamespace='public'::regnamespace and proname like 'board_ui_%'),'board UI authority only belongs to authenticated sessions');
select ok((select bool_and(has_function_privilege('service_role',oid,'EXECUTE') and not has_function_privilege('anon',oid,'EXECUTE') and not has_function_privilege('authenticated',oid,'EXECUTE'))
 from pg_proc where pronamespace='public'::regnamespace and proname like 'board_media_%'),'media byte-verification authority belongs only to service role');
select ok((select bool_and(not has_function_privilege(r,oid,'EXECUTE')) from pg_proc cross join unnest(array['anon','authenticated','service_role'])r
 where pronamespace='private'::regnamespace and proname like 'board_%'),'private board helpers never become callable APIs');
select ok(not (select public from storage.buckets where id='board-quarantine'),'quarantine bucket is private');
select is((select count(*) from private.community_policy),0::bigint,'no active community operating defaults are seeded');
select is((select count(*) from private.board_uploads),0::bigint,'migration creates no uploaded assets');
select is((select count(*) from public.posts),0::bigint,'migration creates no live posts');

create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('c5100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.id(n),'board-unit-'||n||'@example.invalid','{}'::jsonb from generate_series(1,7)n;
update public.profiles set call_name='가상마당팬',onboarding_completed_at=clock_timestamp() where id::text like 'c5100000-%';
update public.profiles set role='admin' where id=pg_temp.id(3);
update public.profiles set onboarding_completed_at=null where id=pg_temp.id(4);
update public.profiles set is_restricted=true where id=pg_temp.id(5);
update public.profiles set is_restricted=true,restricted_until=clock_timestamp()-interval '1 second' where id=pg_temp.id(6);
update public.profiles set role='artist',onboarding_completed_at=null,call_name=null where id=pg_temp.id(7);
insert into public.artists(id,slug,name,grade,status) values
 (pg_temp.id(101),'board-unit','Fictional board artist','B','active'),
 (pg_temp.id(102),'board-paused','Fictional paused artist','B','paused'),
 (pg_temp.id(103),'board-other','Fictional other artist','B','active');
create temporary table board_context(key text primary key,data jsonb);
grant all on board_context to authenticated,service_role;
create function pg_temp.make(p_id integer default 201,p_op integer default 301,p_title text default 'Fictional title',p_body text default 'Fictional body',p_uploads uuid[] default '{}',p_notice boolean default false,p_pinned boolean default false)
returns jsonb language sql as $$select public.board_ui_create('board-unit',pg_temp.id(p_op),pg_temp.id(p_id),pg_temp.id(101),p_title,p_body,p_uploads,p_notice,p_pinned)$$;

set local role anon;
select throws_ok($$select public.board_ui_list('board-unit')$$,'42501',null,'anonymous cannot read board');
select throws_ok($$select pg_temp.make()$$,'42501',null,'anonymous cannot create post');
reset role;
set local role service_role;
select throws_ok($$select public.board_ui_list('board-unit')$$,'42501',null,'service role cannot impersonate UI reader');
select throws_ok($$select pg_temp.make()$$,'42501',null,'service role cannot publish as a user');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select public.board_ui_list('board-unit')$$,'55000','COMMUNITY_POLICY_REQUIRED','board fails closed without configured policy');
select throws_ok($$select pg_temp.make()$$,'55000','COMMUNITY_POLICY_REQUIRED','post creation fails closed without configured policy');
select throws_ok($$select public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(201),'image/png',100,pg_temp.id(501))$$,'42501',null,'fan cannot bypass server byte verification');
reset role;
insert into private.community_policy(version,max_title_length,max_body_length,max_comment_length,max_reason_length,max_images,max_image_bytes,max_image_long_edge,auto_hide_report_count,rate_window_seconds,max_contributions_per_window,max_reports_per_window,forbidden_terms,forbidden_patterns)
values('fictional-board-tests',100,1000,100,100,3,10000,2048,3,60,100,100,array['blockedword'],array['[0-9]{3}-[0-9]{4}-[0-9]{4}']);
set local role authenticated;
select is((public.board_ui_list('board-unit')->'posts'),'[]'::jsonb,'empty board returns actual empty list');
select is(public.board_ui_list('board-unit')->>'actor_id',pg_temp.id(1)::text,'board snapshot binds current actor');
select is((public.board_ui_list('board-unit')->>'can_create_notice')::boolean,false,'fan cannot create notices');
select is(public.board_ui_list('board-unit')->'next_cursor','null'::jsonb,'empty board has no fabricated cursor');
select ok(not (public.board_ui_list('board-unit')->'policy') ? 'forbidden_terms','public limits never disclose moderation terms');
select throws_ok($$select public.board_ui_list('board-unit',0)$$,'22023','BOARD_INVALID_INPUT','zero page limit rejected');
select throws_ok($$select public.board_ui_list('board-unit',101)$$,'22023','BOARD_INVALID_INPUT','unbounded page limit rejected');
select throws_ok($$select public.board_ui_list('board-unit',1,true,null,null)$$,'22023','BOARD_INVALID_INPUT','partial cursor rejected');
select throws_ok($$select public.board_ui_list('board-unit',1,true,'infinity',pg_temp.id(201))$$,'22023','BOARD_INVALID_INPUT','nonfinite cursor timestamp rejected');
select throws_ok($$select public.board_ui_list('board-paused')$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','paused board is unavailable');
select throws_ok($$select public.board_ui_list('missing-board')$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','unknown slug is unavailable');
select throws_ok($$select public.board_ui_create('board-other',pg_temp.id(301),pg_temp.id(201),pg_temp.id(101),'Title','Body','{}',false,false)$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','create checks route slug against locked artist');
select throws_ok($$select pg_temp.make(p_title=>'  ')$$,'23514','COMMUNITY_CONTENT_INVALID','empty title rejected');
select throws_ok($$select pg_temp.make(p_body=>'BLOCKEDWORD')$$,'23514','COMMUNITY_CONTENT_BLOCKED','forbidden content enforced by DB');
select throws_ok($$select pg_temp.make(p_body=>'010-1234-5678')$$,'23514','COMMUNITY_CONTENT_BLOCKED','configured sensitive pattern enforced');
select throws_ok($$select pg_temp.make(p_title=>repeat('a',101))$$,'23514','COMMUNITY_CONTENT_INVALID','approved title bound enforced');
select throws_ok($$select pg_temp.make(p_body=>repeat('a',1001))$$,'23514','COMMUNITY_CONTENT_INVALID','approved body bound enforced');
select throws_ok($$select pg_temp.make(p_notice=>true,p_pinned=>true)$$,'42501','COMMUNITY_FORBIDDEN','fan cannot forge notice flags');
select throws_ok($$select pg_temp.make(p_pinned=>true)$$,'22023','BOARD_INVALID_INPUT','pin requires notice');
select throws_ok($$select pg_temp.make(p_uploads=>array[null]::uuid[])$$,'22023','BOARD_INVALID_INPUT','null upload member rejected');
select throws_ok($$select pg_temp.make(p_uploads=>array[pg_temp.id(501),pg_temp.id(501)])$$,'22023','BOARD_INVALID_INPUT','duplicate image reservation rejected');
insert into board_context values('create',pg_temp.make());
select is(pg_temp.make(),(select data from board_context where key='create'),'exact create retry returns immutable receipt');
select throws_ok($$select pg_temp.make(p_title=>'Changed')$$,'23505','BOARD_OPERATION_CONFLICT','uncertain create cannot silently change payload');
select throws_ok($$select pg_temp.make(p_op=>302)$$,'23505','BOARD_OPERATION_CONFLICT','new operation cannot reuse committed post identity');
select is((select count(*) from public.posts),1::bigint,'duplicate retry creates only one post');
select is((public.board_ui_detail('board-unit',pg_temp.id(201))->'post'->>'body'),'Fictional body','detail returns real persisted body');
select ok((public.board_ui_detail('board-unit',pg_temp.id(201))->'post'->>'is_owner')::boolean,'owner affordance follows current DB identity');
select ok(not (public.board_ui_detail('board-unit',pg_temp.id(201))->'post') ?| array['user_id','request_id','storage_object_id'],'post DTO omits internal actor and storage identifiers');
select is((public.board_ui_detail('board-unit',pg_temp.id(201))->'post'->'author'),' {"call_name":"가상마당팬"}'::jsonb,'author projection exposes only calling name');
select throws_ok($$select public.board_ui_detail('board-other',pg_temp.id(201))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','detail cannot cross route resource');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select ok(not (public.board_ui_detail('board-unit',pg_temp.id(201))->'post'->>'is_owner')::boolean,'other fan gets no owner action');
select throws_ok($$select public.board_ui_delete('board-unit',pg_temp.id(401),pg_temp.id(201),1,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','other fan cannot delete');
select throws_ok($$select public.board_ui_notice('board-unit',pg_temp.id(401),pg_temp.id(201),1,true,true)$$,'42501','COMMUNITY_FORBIDDEN','other fan cannot pin');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
insert into board_context values('notice-create',pg_temp.make(202,302,'Notice','Notice body','{}',true,true));
select is(public.board_ui_list('board-unit',1)->'posts'->0->>'id',pg_temp.id(202)::text,'pinned notice sorts above regular post');
insert into board_context values('page',public.board_ui_list('board-unit',1));
select is(public.board_ui_list('board-unit',1,
 ((select data from board_context where key='page')->'next_cursor'->>'is_pinned')::boolean,
 ((select data from board_context where key='page')->'next_cursor'->>'created_at')::timestamptz,
 ((select data from board_context where key='page')->'next_cursor'->>'id')::uuid)->'posts'->0->>'id',pg_temp.id(201)::text,'cursor crosses pinned to normal without duplicate');
select throws_ok($$select public.board_ui_delete('board-unit',pg_temp.id(401),pg_temp.id(201),1,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','board delete is owner-only even for admin; moderation remains separate');
select throws_ok($$select public.board_ui_notice('board-other',pg_temp.id(401),pg_temp.id(201),1,true,true)$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','notice checks route binding');
insert into board_context values('notice',public.board_ui_notice('board-unit',pg_temp.id(401),pg_temp.id(201),1,true,true));
select is((select data->>'revision' from board_context where key='notice'),'2','notice mutation advances revision');
select is(public.board_ui_notice('board-unit',pg_temp.id(401),pg_temp.id(201),1,true,true),(select data from board_context where key='notice'),'notice retry returns original immutable receipt');
select throws_ok($$select public.board_ui_notice('board-unit',pg_temp.id(401),pg_temp.id(201),1,false,false)$$,'23505','BOARD_OPERATION_CONFLICT','notice retry cannot change operation flags');
select throws_ok($$select public.board_ui_notice('board-unit',pg_temp.id(402),pg_temp.id(201),1,false,false)$$,'40001','BOARD_REVISION_CONFLICT','stale admin toggle rejected');
select is(public.board_ui_notice('board-unit',pg_temp.id(402),pg_temp.id(201),2,true,true)->>'revision','2','unchanged flags do not create a false revision');
reset role;
select is((select count(*) from public.community_moderation_log where target_id=pg_temp.id(201) and action='notice'),1::bigint,'retry and no-op do not duplicate notice audit');
select throws_ok($$update private.board_operations set response='{}'$$,'55000','BOARD_OPERATION_IMMUTABLE','receipts cannot be rewritten');
select throws_ok($$delete from private.board_operations$$,'55000','BOARD_OPERATION_IMMUTABLE','receipts cannot be deleted');
select throws_ok($$truncate private.board_operations$$,'55000','BOARD_OPERATION_IMMUTABLE','receipts cannot be truncated');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select public.board_ui_delete('board-unit',pg_temp.id(403),pg_temp.id(201),2,false)$$,'22023','BOARD_CONFIRMATION_REQUIRED','deletion needs explicit confirmation');
select throws_ok($$select public.board_ui_delete('board-unit',pg_temp.id(403),pg_temp.id(201),9007199254740991,true)$$,'22023','BOARD_INVALID_INPUT','delete rejects revision that would overflow on increment');
select throws_ok($$select public.board_ui_delete('board-unit',pg_temp.id(403),pg_temp.id(201),1,true)$$,'40001','BOARD_REVISION_CONFLICT','stale owner deletion rejected');
select throws_ok($$select public.board_ui_delete('board-other',pg_temp.id(403),pg_temp.id(201),2,true)$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','delete checks route binding');
insert into board_context values('delete',public.board_ui_delete('board-unit',pg_temp.id(403),pg_temp.id(201),2,true));
select is(public.board_ui_delete('board-unit',pg_temp.id(403),pg_temp.id(201),2,true),(select data from board_context where key='delete'),'delete unknown-outcome replay returns receipt');
select throws_ok($$select public.board_ui_detail('board-unit',pg_temp.id(201))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','deleted post disappears even for owner');
select is(jsonb_array_length(public.board_ui_list('board-unit')->'posts'),1,'soft deletion removes board entry');
reset role;
select ok((select deleted_at is not null and is_hidden and not is_pinned from public.posts where id=pg_temp.id(201)),'owner delete is soft and unpins terminal content');
select is((select count(*) from private.point_ledger),0::bigint,'missing reward policy causes no invented awards');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(4)::text,true);
select throws_ok($$select public.board_ui_list('board-unit')$$,'42501','COMMUNITY_FORBIDDEN','incomplete fan onboarding denied');
select set_config('request.jwt.claim.sub',pg_temp.id(5)::text,true);
select throws_ok($$select public.board_ui_list('board-unit')$$,'42501','COMMUNITY_FORBIDDEN','restricted actor cannot read');
select throws_ok($$select pg_temp.make(203,303)$$,'42501','COMMUNITY_FORBIDDEN','restricted actor cannot create');
select set_config('request.jwt.claim.sub',pg_temp.id(6)::text,true);
select lives_ok($$select public.board_ui_list('board-unit')$$,'expired restriction permits read');
select set_config('request.jwt.claim.sub',pg_temp.id(7)::text,true);
select lives_ok($$select pg_temp.make(203,303)$$,'artist follows existing community author permission without paid subscription');
select is(public.board_ui_detail('board-unit',pg_temp.id(203))->'post'->'author'->'call_name','null'::jsonb,'optional calling name remains explicitly null');
reset role;
update public.posts set is_hidden=true where id=pg_temp.id(203);
set local role authenticated;
select throws_ok($$select public.board_ui_detail('board-unit',pg_temp.id(203))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','hidden post unavailable even to author');
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select throws_ok($$select public.board_ui_detail('board-unit',pg_temp.id(203))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','board does not become admin moderation view');
select throws_ok($$select public.board_ui_notice('board-unit',pg_temp.id(404),pg_temp.id(203),2,true,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','notice controls cannot revive hidden content');
reset role;

-- Ordinary functional Storage metadata fixtures only; actual file sanitization
-- is tested by application adapters, not claimed by these SQL metadata checks.
set local role service_role;
insert into board_context values('upload',public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(204),'image/png',100,pg_temp.id(501)));
select is(public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(204),'image/png',100,pg_temp.id(501)),(select data from board_context where key='upload'),'begin retry reuses immutable upload reservation');
select throws_ok($$select public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(204),'image/jpeg',100,pg_temp.id(501))$$,'23505','BOARD_OPERATION_CONFLICT','upload request cannot change MIME');
select throws_ok($$select public.board_media_resolve_upload(pg_temp.id(2),((select data from board_context where key='upload')->>'upload_id')::uuid)$$,'42501','COMMUNITY_FORBIDDEN','foreign actor cannot inspect upload');
select throws_ok($$select public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(204),'text/html',100,pg_temp.id(502))$$,'23514','BOARD_IMAGE_INVALID','unsupported image MIME rejected');
select throws_ok($$select public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(204),'image/png',10001,pg_temp.id(502))$$,'23514','BOARD_IMAGE_INVALID','approved byte cap enforced on begin');
select throws_ok($$select public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(201),'image/png',100,pg_temp.id(502))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','cannot add images to committed posts through staging');
select throws_ok($$select public.board_media_finalize_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid,pg_temp.id(601),100,100)$$,'23514','BOARD_IMAGE_INVALID','completion requires real matching final Storage identity');
reset role;
select is((select count(*) from public.posts where id=pg_temp.id(204)),0::bigint,'upload reservation publishes no partial post');
insert into storage.objects(id,bucket_id,name,metadata) values(pg_temp.id(601),'board-media',(select data->>'object_path' from board_context where key='upload'),' {"mimetype":"image/png","size":90}'::jsonb);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select pg_temp.make(204,304,p_uploads=>array[((select data from board_context where key='upload')->>'upload_id')::uuid])$$,'23514','BOARD_IMAGE_INVALID','pending image cannot publish partial post');
reset role;
select is((select count(*) from public.posts where id=pg_temp.id(204)),0::bigint,'failed attachment rolls back post creation');
set local role service_role;
select throws_ok($$select public.board_media_finalize_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid,pg_temp.id(601),2049,100)$$,'23514','BOARD_IMAGE_INVALID','approved image long-edge bound enforced');
select is(public.board_media_finalize_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid,pg_temp.id(601),100,100),((select data from board_context where key='upload')->>'image_id')::uuid,'sanitized final bytes may differ from source size');
select is(public.board_media_finalize_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid,pg_temp.id(601),100,100),((select data from board_context where key='upload')->>'image_id')::uuid,'exact finalize retry succeeds once');
select throws_ok($$select public.board_media_finalize_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid,pg_temp.id(601),99,100)$$,'23505','BOARD_OPERATION_CONFLICT','finalize replay cannot change dimensions');
select throws_ok($$select public.board_media_resolve_read(pg_temp.id(1),((select data from board_context where key='upload')->>'image_id')::uuid)$$,'42501',null,'staged verified images grant no read URL authority');
reset role;
update private.community_policy set max_image_long_edge=99;
set local role service_role;
select throws_ok($$select public.board_media_resolve_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid)$$,'23514','BOARD_IMAGE_INVALID','completed reservation rechecks current dimension policy');
reset role;
update private.community_policy set max_image_long_edge=2048;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select throws_ok($$select pg_temp.make(204,304,p_uploads=>array[((select data from board_context where key='upload')->>'upload_id')::uuid])$$,'23514','BOARD_IMAGE_INVALID','foreign user cannot attach another actor image');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select lives_ok($$select pg_temp.make(204,304,p_uploads=>array[((select data from board_context where key='upload')->>'upload_id')::uuid])$$,'completed owned images attach atomically with post');
select is(jsonb_array_length(public.board_ui_detail('board-unit',pg_temp.id(204))->'post'->'images'),1,'detail exposes completed attached image');
select ok(not (public.board_ui_detail('board-unit',pg_temp.id(204))->'post'->'images'->0) ?| array['object_path','bucket_id','storage_object_id'],'image DTO never leaks storage locators');
reset role;
select is((select count(*) from public.post_images where post_id=pg_temp.id(204)),1::bigint,'one verified image metadata row attached');
select ok((select attached_at is not null from private.board_uploads where id=((select data from board_context where key='upload')->>'upload_id')::uuid),'reservation marked attached in create transaction');
set local role service_role;
select is(public.board_media_revoke_upload(pg_temp.id(1),((select data from board_context where key='upload')->>'upload_id')::uuid),false,'attached image cannot be detached via upload revoke');
select is(public.board_media_resolve_read(pg_temp.id(2),((select data from board_context where key='upload')->>'image_id')::uuid)->>'bucket_id','board-media','any eligible fan can view visible free-board image');
select ok((public.board_media_resolve_read(pg_temp.id(2),((select data from board_context where key='upload')->>'image_id')::uuid)->>'access_expires_at')::timestamptz<=clock_timestamp()+interval '60 seconds','protected read grant has bounded technical TTL');
select throws_ok($$select public.board_media_resolve_read(pg_temp.id(5),((select data from board_context where key='upload')->>'image_id')::uuid)$$,'42501','COMMUNITY_FORBIDDEN','restricted reader cannot obtain image grant');
insert into board_context values('revoke',public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(205),'image/png',100,pg_temp.id(502)));
select is(public.board_media_revoke_upload(pg_temp.id(1),((select data from board_context where key='revoke')->>'upload_id')::uuid),true,'unpublished upload can be revoked');
select is(public.board_media_revoke_upload(pg_temp.id(1),((select data from board_context where key='revoke')->>'upload_id')::uuid),true,'revoke is idempotent');
select throws_ok($$select public.board_media_resolve_upload(pg_temp.id(1),((select data from board_context where key='revoke')->>'upload_id')::uuid)$$,'42501','BOARD_UPLOAD_REVOKED','revoked upload cannot be completed later');
insert into board_context values('expire',public.board_media_begin_upload(pg_temp.id(1),pg_temp.id(101),pg_temp.id(205),'image/png',100,pg_temp.id(503)));
reset role;
update private.board_uploads set created_at=clock_timestamp()-interval '3 hours',expires_at=clock_timestamp()-interval '1 hour' where id=((select data from board_context where key='expire')->>'upload_id')::uuid;
set local role service_role;
select throws_ok($$select public.board_media_resolve_upload(pg_temp.id(1),((select data from board_context where key='expire')->>'upload_id')::uuid)$$,'55000','BOARD_UPLOAD_EXPIRED','expired reservation cannot publish');
reset role;
create temporary table board_saved_policy as table private.community_policy;
delete from private.community_policy;
set local role service_role;
select throws_ok($$select public.board_media_resolve_read(pg_temp.id(1),((select data from board_context where key='upload')->>'image_id')::uuid)$$,'55000','COMMUNITY_POLICY_REQUIRED','known image read fails closed when policy is removed');
reset role;
insert into private.community_policy select * from board_saved_policy;
update public.posts set is_hidden=true where id=pg_temp.id(204);
set local role service_role;
select throws_ok($$select public.board_media_resolve_read(pg_temp.id(1),((select data from board_context where key='upload')->>'image_id')::uuid)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','hidden content revokes image authority even from owner');
reset role;
update public.posts set is_hidden=false where id=pg_temp.id(204);
update public.artists set status='paused' where id=pg_temp.id(101);
set local role service_role;
select throws_ok($$select public.board_media_resolve_read(pg_temp.id(1),((select data from board_context where key='upload')->>'image_id')::uuid)$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','artist pause revokes board image grant');
reset role;
update public.artists set status='active' where id=pg_temp.id(101);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select lives_ok($$select public.community_set_notice(pg_temp.id(204),true,true)$$,'legacy notice RPC remains compatible');
select throws_ok($$select public.board_ui_notice('board-unit',pg_temp.id(405),pg_temp.id(204),1,false,false)$$,'40001','BOARD_REVISION_CONFLICT','legacy updates invalidate new CAS forms');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select lives_ok($$select public.community_create_post(pg_temp.id(101),pg_temp.id(305),'Legacy title','Legacy body')$$,'legacy post creation remains compatible');
reset role;
select * from finish();
rollback;
